nowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Xactimate estimating","Ice dam claims","Sewer backup claims","Hail damage"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://michiganinsuranceappraiser.com/#website","url":"https://michiganinsuranceappraiser.com/","name":"Michigan Insurance Appraiser","publisher":{"@id":"https://michiganinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://michiganinsuranceappraiser.com/michigan-appraisal-process/#webpage","url":"https://michiganinsuranceappraiser.com/michigan-appraisal-process/","name":"How Insurance Appraisal Works in Michigan | 8 Steps","description":"How insurance appraisal works in Michigan, in eight steps: the written demand, choosing appraisers, the umpire, the award and getting paid.","inLanguage":"en-US","isPartOf":{"@id":"https://michiganinsuranceappraiser.com/#website"},"about":{"@id":"https://michiganinsuranceappraiser.com/#business"},"publisher":{"@id":"https://michiganinsuranceappraiser.com/#business"},"dateModified":"2026-11-17","primaryImageOfPage":{"@type":"ImageObject","url":"https://michiganinsuranceappraiser.com/assets/img/photos/meeting.webp","width":1200,"height":800},"breadcrumb":{"@id":"https://michiganinsuranceappraiser.com/michigan-appraisal-process/#breadcrumb"},"mainEntity":{"@id":"https://michiganinsuranceappraiser.com/michigan-appraisal-process/#howto"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://michiganinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Appraisal process","item":"https://michiganinsuranceappraiser.com/michigan-appraisal-process/"}],"@id":"https://michiganinsuranceappraiser.com/michigan-appraisal-process/#breadcrumb"},{"@type":"HowTo","name":"How insurance appraisal works in Michigan","description":"The eight stages of a property insurance appraisal under a Michigan policy.","totalTime":"P10W","step":[{"@type":"HowToStep","position":1,"name":"Document the gap in numbers","text":"Put your figure and the insurer’s figure side by side, line by line, so the dollar gap is clear. Appraisal works best when the argument is about price and quantity, not about whether the loss is covered.","url":"https://michiganinsuranceappraiser.com/michigan-appraisal-process/"},{"@type":"HowToStep","position":2,"name":"Read the appraisal clause","text":"Find the appraisal provision in your policy and note its exact wording, notice rules and any timing language. Michigan law requires this provision in property policies, but the details still come from your contract.","url":"https://michiganinsuranceappraiser.com/michigan-appraisal-process/"},{"@type":"HowToStep","position":3,"name":"Send a written demand","text":"Either side can start the process with a clear written demand for appraisal sent to the insurer. Keep proof of when and how it was delivered.","url":"https://michiganinsuranceappraiser.com/michigan-appraisal-process/"},{"@type":"HowToStep","position":4,"name":"Each side names an appraiser","text":"You and the insurer each pick a competent, independent appraiser, generally within 20 days of the demand. Your appraiser builds and presents the valuation for your side.","url":"https://michiganinsuranceappraiser.com/michigan-appraisal-process/"},{"@type":"HowToStep","position":5,"name":"Appraisers select an umpire","text":"The two appraisers try to agree on a neutral umpire, generally within 15 days. If they can’t agree, either side can ask a Michigan court of record to choose one.","url":"https://michiganinsuranceappraiser.com/michigan-appraisal-process/"},{"@type":"HowToStep","position":6,"name":"Inspect and exchange estimates","text":"The appraisers walk the property, review photos, invoices and estimates, and trade detailed line-item valuations. Many items settle at this stage once both sides see the same evidence.","url":"https://michiganinsuranceappraiser.com/michigan-appraisal-process/"},{"@type":"HowToStep","position":7,"name":"Resolve the remaining items","text":"Items the two appraisers can’t agree on go to the umpire with supporting documents. The umpire weighs each disputed item and sides with the better-supported number or sets a figure between them.","url":"https://michiganinsuranceappraiser.com/michigan-appraisal-process/"},{"@type":"HowToStep","position":8,"name":"Sign the award and get paid","text":"A written award signed by any two of the three sets the amount of loss. The insurer then pays under the policy terms, less the deductible and prior payments, with any holdback handled as the policy allows.","url":"https://michiganinsuranceappraiser.com/michigan-appraisal-process/"}],"@id":"https://michiganinsuranceappraiser.com/michigan-appraisal-process/#howto"}]}</script>
